// Google Sheets gives flat rows. The template expects nested JSON:
//   { cust_first_name, cust_last_name, cust_city, orders: [ { order_name, order_total, product: [...] } ] }
// Group the rows by customer, then by order.

const customers = new Map();

for (const row of $input.all().map((item) => item.json)) {
	const key = `${row.cust_first_name} ${row.cust_last_name}`;

	if (!customers.has(key)) {
		customers.set(key, {
			cust_first_name: row.cust_first_name,
			cust_last_name: row.cust_last_name,
			cust_city: row.cust_city,
			orders: [],
		});
	}

	const customer = customers.get(key);
	let order = customer.orders.find((o) => o.order_name === row.order_name);

	if (!order) {
		order = { order_name: row.order_name, order_total: 0, product: [] };
		customer.orders.push(order);
	}

	const quantity = Number(row.quantity);
	const unitPrice = Number(row.unit_price);

	order.product.push({ product_name: row.product_name, quantity, unit_price: unitPrice });
	order.order_total += quantity * unitPrice;
}

// One item per customer, so Cloud Office Print runs once per customer.
return [...customers.values()].map((customer) => ({
	json: {
		fileName: `invoice-${customer.cust_first_name}-${customer.cust_last_name}`.toLowerCase(),
		copData: customer,
	},
}));
